def flipLights(n: int, m: int) -> int:
    n = min(n, 3)

    if m == 0:
        return 1

    states = set()

    for presses in range(m + 1):
        for state in range(1 << n):
            new_state = state

            if presses > 0:
                # Button 1: Toggle all bulbs
                new_state ^= (1 << n) - 1

            if presses > 1:
                # Button 2: Toggle even bulbs
                for i in range(1, n + 1):
                    if i % 2 == 0:
                        new_state ^= (1 << (i - 1))

            if presses > 2:
                # Button 3: Toggle odd bulbs
                for i in range(1, n + 1):
                    if i % 2 == 1:
                        new_state ^= (1 << (i - 1))

            if presses > 3:
                # Button 4: Toggle bulbs of the form 3k + 1
                for i in range(1, n + 1):
                    if (i - 1) % 3 == 0:
                        new_state ^= (1 << (i - 1))

            states.add(new_state)

    return len(states)
