def isIdealPermutation(A: List[int]) -> bool:
    local_inversions = 0
    global_inversions = 0
    n = len(A)

    # Count local inversions
    for i in range(n - 1):
        if A[i] > A[i + 1]:
            local_inversions += 1

    # Count global inversions
    for i in range(n):
        for j in range(i + 1, min(i + 2, n)):  # Only check the next index
            if A[i] > A[j]:
                global_inversions += 1

    return local_inversions == global_inversions

