def divide(dividend: int, divisor: int) -> int:
    if dividend == 0:
        return 0
    if dividend == -2**31 and divisor == -1:
        return 2**31 - 1

    sign = 1
    if (dividend < 0) ^ (divisor < 0):
        sign = -1

    dividend, divisor = abs(dividend), abs(divisor)
    quotient = 0
    multiple = 1

    while dividend >= (divisor << 1):
        divisor <<= 1
        multiple <<= 1

    while dividend >= divisor:
        dividend -= divisor
        quotient += multiple

    quotient *= sign

    if quotient > 2**31 - 1:
        return 2**31 - 1
    if quotient < -2**31:
        return -2**31

    return quotient
