def addOperators(num: str, target: int) -> List[str]:
    results = []

    def dfs(index: int, current_expression: str, current_value: int, last_operand: int):
        if index == len(num):
            if current_value == target:
                results.append(current_expression)
            return

        for i in range(index, len(num)):
            # Avoid leading zeros
            if i > index and num[index] == '0':
                break

            operand = int(num[index:i + 1])
            if index == 0:
                # First operand, no operator needed
                dfs(i + 1, current_expression + str(operand), operand, operand)
            else:
                # Addition
                dfs(i + 1, current_expression + '+' + str(operand), current_value + operand, operand)
                # Subtraction
                dfs(i + 1, current_expression + '-' + str(operand), current_value - operand, -operand)
                # Multiplication
                dfs(i + 1, current_expression + '*' + str(operand), current_value - last_operand + (last_operand * operand), last_operand * operand)

    dfs(0, "", 0, 0)
    return results

